import{_ as e,o as t,c as p,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/48-孤单的旅人.md","filePath":"books/attached/48-孤单的旅人.md","lastUpdated":1794316978000}'),r={name:"books/attached/48-孤单的旅人.md"};function s(_,a,n,d,c,i){return t(),p("div",null,[...a[0]||(a[0]=[o('<h3 id="孤单的旅人" tabindex="-1">孤单的旅人 <a class="header-anchor" href="#孤单的旅人" aria-label="Permalink to &quot;孤单的旅人&quot;">​</a></h3><p>我们总是觉得那些独自环游世界的人非常酷炫，他们将一切负担和责任抛到一边，四海为家也毫无顾忌。从传奇影视形象阿甘，到现实生活中的典范、著名生态学家戴安·福西（Diane Fossey），这类孤单的旅行者，往往都自带着非常强烈的信念以及理想化的动机。</p><p>在乔恩·克拉考尔（Jon Krakauer）的畅销小说《荒野生存》（Into The Wild）中，主人公克里斯·麦坎德斯（Chris McCandless）在二十岁出头时，放弃了全优生和运动健将的身份，放弃了安稳有序的生活，而投身进阿拉斯加的荒野中去。克里斯独自一人，轻装上阵开始了阿拉斯加之旅，他的目标就是在没有任何他人帮助的情况下，在那片土地上生存下来。在旅途中，克里斯遇到了一些想与他发生点儿联结的人，比如一位想要收养他的老人、一位爱上他的年轻女孩，以及一对邀请他同住的夫妇。但是克里斯始终选择了踽踽独行。</p><p>在到达目的地之前，克里斯与旅行中最后一个产生交集的人相遇了，这个名叫加力安（Gallien）的男人载了他一程，小说原文是这样说的：</p><p>在一路向南，开往山野的途中，加力安多次试着劝阻艾利克斯（克里斯的假名字）的计划，说那毫无意义。他甚至愿意载着艾利克斯到阿拉斯加的城市安克雷奇（Anchorage），让他好歹能买些体面的用品。但是艾利克斯却婉言谢绝：“我有这些就够了。”当加力安问起，艾利克斯的父母和亲友是不是知道他的这次出行，好歹遭遇不测的时候可以有个人知道他的处境，艾利克斯的否定回答非常明确而冷静。事实上，他已经近三年没有和家里人沟通过了，他回答加力安：“我好得很，绝对不会令自己陷入无法掌控的局面。”</p><p>在与加力安分别以后，克里斯穿越了一条冰河，真正地深深投入一片与世隔绝的原始丛林中。在那几个月的时间里，克里斯以捕猎为生。而到了次年的春天，克里斯想要回到家里的时候，他却发现之前趟过的那条河里，冰雪已经融化，河水已经涨起来，湍急的洪流阻挡了他回归文明社会的路。别无选择的克里斯回到了他在原始丛林中的驻地，并在那里终其一生。在生命的最后一天，他在游记中写道：“只有能和他人分享的，才是真正的幸福。”</p><p>似乎有这样一条不成文的公理，我们都觉得回避型依恋风格的人在生活与亲密关系中，扮演着一位孤独的旅人。比如像克里斯，他们都曾向往着独立自主的生活，而不太认同依恋感。但是作为一位回避型的人，或许克里斯临死前的感悟也会对你追求幸福有所帮助：一切的阅历，是因为与他人的分享，才被赋予了意义。</p><p>在这一节中我们着重探讨这些孤独旅行者的生活方式，回避型的人即使与深爱的人在一起时，也会努力与对方保持距离。在此，我们会帮助回避型的人探寻亲密关系中被动行为的原因，以及如何改观自己的行为，以便在今后的恋爱关系中，得到真正的愉悦与幸福。若是你并不属于回避型依恋风格，这个章节也能在你遇到回避型的人，或是今后万一遇到这样的人时，帮助你理解他们的行为。</p><p>生存优势并不等于爱情自如</p><p>毋庸置疑，每种依恋风格的存在，都是在特定环境之下，人们为了增加自己的生存概率而产生的。而其中安全依恋风格似乎最为奏效。纵观史前时代我们的祖先，他们主要通过紧密相连的集群来工作和生活，这似乎是保证族群未来和后代安全的最优方式。但是，为了保证族群在任何条件下都能获得蓬勃的生存优势，我们的祖先或许还需要一些别的策略来辅助。比如说那些生存条件非常恶劣的时代，大量的人类在都遭受着饥荒或自然灾害，这时候，通过某种独特的能力，获取比同类更多的生存可能，就显得至关重要。而这时候个体就会相互割裂，更加独立自主，由此在极端自然环境下，将会有更强的能力来抢占有限的资源。正是与他人这种割裂的本能，慢慢发展成为了人类群体中的回避型依恋风格人群。</p><p>但是，在人类种群之中的生存优势，迁移到回避型人群的感情领域，可就算不上什么优势了。如果克里斯·麦坎德斯一开始愿意与他人协作，或许就不会丢了性命。也有研究表明，事实上回避型依恋风格的人群，在亲密关系中的幸福感和满意度的确相对较低。</p><p>不过所幸，回避型的人也可以改变自己的行为方式，实在不必屈服于自己的原始冲动和进化本能。可以学习一下如何克服自己下意识的行为，试着变得主动一些，或许能够获得更加有益的亲密关系。</p>',12)])])}const m=e(r,[["render",s]]);export{h as __pageData,m as default};
